const crmContentOnLoad=document.querySelector('.crm-content');
const adminLoginOnLoad=document.getElementById('admin-login');
const operatorToolsOnLoad=document.getElementById('crm-operator-tools');
const restoreAdminSession=async()=>{if(!crmContentOnLoad||!adminLoginOnLoad)return;try{const response=await fetch('/api/me',{credentials:'include'});const session=await response.json();if(!session.authenticated||!session.user||session.user.role!=='admin')return;const csrf=await fetch('/api/csrf',{credentials:'include'});const csrfData=await csrf.json();if(!csrf.ok||!csrfData.csrf_token)return;window.crmCsrf=csrfData.csrf_token;crmContentOnLoad.hidden=false;adminLoginOnLoad.hidden=true;if(operatorToolsOnLoad)operatorToolsOnLoad.hidden=false;const [cases,customers,followups]=await Promise.all(['/api/cases','/api/customers','/api/followups'].map(async path=>{const result=await fetch(path,{credentials:'include'});if(!result.ok)throw new Error('Live data unavailable');return result.json();}));const caseCount=document.getElementById('live-case-count');const customerCount=document.getElementById('live-customer-count');const followupCount=document.getElementById('live-followup-count');if(caseCount)caseCount.textContent=cases.cases.length;if(customerCount)customerCount.textContent=customers.customers.length;if(followupCount)followupCount.textContent=followups.followups.length;const status=document.getElementById('live-admin-status');if(status)status.textContent='Production records loaded.';}catch(error){}}
restoreAdminSession();
